-- Bare-column tenancy: the default Missions page in Anvil with the capability booleans, as the walkthrough issued it (parameters bound to literals).
SELECT Id, SectorId, ClientId, KindId, Title, Brief, BriefingTemplateId, Hazard, Fee, Deadline, RequiredCertId, BookedBy, AssignedSquadronId, StatusId, Notes, Settlement, ARRAY<BOOL>[(`Missions`.`StatusId` IN ('open')), (`Missions`.`StatusId` IN ('claimed')), (`Missions`.`StatusId` IN ('underway')), (`Missions`.`StatusId` IN ('on_hold')), (`Missions`.`StatusId` IN ('completed', 'failed', 'stood_down'))] AS zzCapabilityChecks FROM Missions WHERE (`Missions`.`SectorId` = 'anvil') ORDER BY `Deadline` ASC, `Id` ASC LIMIT 26
